#ifndef PARSER_HPP
#define PARSER_HPP

#include <string>
#include <istream>
#include <sstream>
#include <iostream>

class Memory;

class Parser {
public:
    static unsigned parse_hex(const std::string &hex);
    static void parse(std::istream &in, Memory &mem);
    static void parse_hex(std::istream &in, Memory &mem);
};

unsigned Parser::parse_hex(const std::string &hex) {
    unsigned value = 0;
    std::stringstream ss(hex);
    ss >> std::hex >> value;
    if (ss.fail() || !ss.eof()) {
        std::cerr << "Invalid hex string: " << hex << std::endl;
        return 0;
    }
    return value;
}

void Parser::parse(std::istream &in, Memory &mem) {
    std::string line;
    unsigned base_address = 0;
    while (std::getline(in, line)) {
        if (!line.empty() && line[0] == '@') {
            base_address = parse_hex(line.substr(1));
        } else {
            for (size_t i = 0; i < line.length(); i += 2) {
                std::string byte_str = line.substr(i, 2);
                unsigned byte_value = parse_hex(byte_str);
                mem.write(base_address + i / 2, static_cast<uint8_t>(byte_value));
            }
        }
    }
}

void Parser::parse_hex(std::istream &in, Memory &mem) {
    std::string line;
    unsigned address = 0;
    while (std::getline(in, line)) {
        for (size_t i = 0; i < line.length(); i += 8) {
            std::string dword_str = line.substr(i, 8);
            unsigned dword_value = parse_hex(dword_str);
            mem.write(address + i / 2, static_cast<uint32_t>(dword_value));
        }
        address += line.length() / 2;
    }
}

#endif // PARSER_HPP
